import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Context Engineering: 4 ways a context window fails, and the one you wrote yourself","description":"","frontmatter":{"url":"https://x.com/hanakoxbt/status/2081800965502513286","title":"Context Engineering: 4 ways a context window fails, and the one you wrote yourself","author":"hanakoxbt","archived":"2026-07-30T00:00:00.000Z","handle":"@hanakoxbt","published":"2026-07-27T00:00:00.000Z","stats":"31 likes · 5 retweets · 40 bookmarks · 9419 views","tags":["context-engineering","claude-md","skills","compaction","progressive-disclosure","subagent-isolation"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-27-@hanakoxbt-513286.md","filePath":"research/tweets/2026-07-27-@hanakoxbt-513286.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-27-@hanakoxbt-513286.md"};function i(r,e,l,p,h,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="context-engineering-4-ways-a-context-window-fails-and-the-one-you-wrote-yourself-—-hanakoxbt" tabindex="-1">Context Engineering: 4 ways a context window fails, and the one you wrote yourself — @hanakoxbt <a class="header-anchor" href="#context-engineering-4-ways-a-context-window-fails-and-the-one-you-wrote-yourself-—-hanakoxbt" aria-label="Permalink to &quot;Context Engineering: 4 ways a context window fails, and the one you wrote yourself — @hanakoxbt&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/hanakoxbt/status/2081800965502513286" target="_blank" rel="noreferrer">https://x.com/hanakoxbt/status/2081800965502513286</a><strong>作者</strong>：hanakoxbt（@hanakoxbt） <strong>發布日期</strong>：2026-07-27 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：31 likes · 5 retweets · 40 bookmarks · 9419 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Everyone optimizes the forty-five tokens they type.</p><p>Nobody has ever opened the seven thousand eight hundred that load before them.</p><p>That is the actual ratio.</p><p>Before you type a single character, Claude Code has already filled its window.</p><p>Your request is barely half a percent of what the model is reading.</p><p>The rest reloads on every single request, for the life of the project.</p><p>A bad prompt costs you one answer.</p><p>A bad line of context costs you a fraction of every answer Claude will ever give you here.</p><p>This is the discipline that fixes that.</p><p>Not writing better instructions.</p><p>Engineering the window they live in.</p><hr><h2 id="what-is-already-in-the-window-before-you-speak" tabindex="-1">What is already in the window before you speak <a class="header-anchor" href="#what-is-already-in-the-window-before-you-speak" aria-label="Permalink to &quot;What is already in the window before you speak&quot;">​</a></h2><p>Anthropic publishes a session simulation with representative token counts.</p><p>The shape of it is the whole argument.</p><p>The system prompt lands first.</p><p>Auto memory follows, capped at the first 200 lines or 25KB, whichever comes first.</p><p>Then environment info, MCP tool names, one-line skill descriptions, your global CLAUDE.md, and the project CLAUDE.md.</p><p>That is roughly 7,850 tokens before your prompt exists.</p><p>Then you type your actual request.</p><p>Forty-five tokens.</p><p>Prompt engineering optimizes those forty-five.</p><p>Context engineering optimizes the 7,850.</p><p>And unlike your prompt, they reload every time.</p><p>[圖 1]</p><p>Those numbers are representative. Yours are not.</p><p>Claude Code ships a command that prints your real window.</p><p>Run /context and you get a colored grid plus a per-category breakdown.</p><p>System prompt, system tools, MCP tools, custom agents, memory files, messages, free space, autocompact buffer.</p><p>It tells you which files loaded and which tool calls ate the most tokens.</p><p>Two habits separate people who engineer context from people who guess at it.</p><p>Run /context at the start of a session to see your fixed overhead.</p><p>If memory files are taking meaningful space, your CLAUDE.md is too long, and you just diagnosed it in one command.</p><p>Then run it again mid-session, rather than waiting for Claude to warn you.</p><p>Pair it with /memory to open the exact files that loaded.</p><p>And /usage to break recent spend down by skills, subagents, plugins, and individual MCP servers.</p><hr><h2 id="the-four-ways-it-fails" tabindex="-1">The four ways it fails <a class="header-anchor" href="#the-four-ways-it-fails" aria-label="Permalink to &quot;The four ways it fails&quot;">​</a></h2><p>&quot;Too much context&quot; is not a diagnosis.</p><p>Drew Breunig catalogued four distinct failure modes.</p><p>Naming them turns a vague sense that Claude is being dumb into a specific thing you can go fix.</p><p>Poisoning.</p><p>A hallucination makes it into context and everything downstream builds on it.</p><p>The model is not wrong once. It is wrong consistently, from a bad premise it now treats as given.</p><p>Distraction.</p><p>The accumulated context grows so large it overwhelms what the model knows from training.</p><p>It stops reasoning and starts pattern-matching against the pile you handed it.</p><p>Confusion.</p><p>Superfluous context influences the response.</p><p>This is the classic symptom of loading tools and files that have nothing to do with the task.</p><p>The model reaches for something that was in the window rather than something that was right.</p><p>Clash.</p><p>Parts of the context disagree with each other.</p><p>Three of those arrive on their own.</p><p>The fourth you author yourself.</p><p>Anthropic found it in their own transcripts.</p><p>A single request arriving with one source saying to document as appropriate, another saying never add comments, and a user asking for something else again.</p><p>Claude generally reads intent and lands on the right answer.</p><p>But it has to think harder to reconcile the contradiction first.</p><p>You pay that tax on every request, invisibly, because the output still looks fine.</p><p>That is what makes clash the expensive one.</p><p>Poisoning is loud.</p><p>Clash is silent and permanent, sitting in a file you wrote six months ago and have not read since.</p><p>[圖 2]</p><h2 id="delete-first-measure-second" tabindex="-1">Delete first, measure second <a class="header-anchor" href="#delete-first-measure-second" aria-label="Permalink to &quot;Delete first, measure second&quot;">​</a></h2><p>The headline number is the argument.</p><p>Anthropic removed over 80% of Claude Code&#39;s system prompt for the Claude 5 generation.</p><p>Their coding evaluations showed no measurable loss.</p><p>Not a rewrite.</p><p>A deletion, of guidance that felt load-bearing right up until it was gone.</p><p>Invert your default.</p><p>Most people treat context as innocent until proven harmful. It is one line, what is the harm.</p><p>Treat it as guilty until proven useful.</p><p>The method is unglamorous and it works.</p><ol><li>Build the smallest eval harness you can stand. Ten prompts you care about, a rubric for what good looks like. Without it you are guessing.</li><li>Cut a whole block, never a single line. One sentence at a time sits inside the noise floor and tells you nothing.</li><li>Run the harness. If nothing moves, the cut stays.</li><li>Restore only what actually broke. You will be surprised how rarely you restore.</li></ol><hr><h2 id="trade-rules-for-judgement" tabindex="-1">Trade rules for judgement <a class="header-anchor" href="#trade-rules-for-judgement" aria-label="Permalink to &quot;Trade rules for judgement&quot;">​</a></h2><p>When Claude Code first shipped, the priority was avoiding worst cases.</p><p>That justified guidance stated far more strongly than it was actually true.</p><p>The old system prompt told Claude to default to no comments, never write multi-paragraph docstrings, never create planning documents unless asked.</p><p>Absolute, unconditional, easy to follow.</p><p>And wrong for a real slice of prompts, since some users want documentation and some genuinely complex code needs a multi-line block.</p><p>With older models the comments Claude wrote were incorrect often enough that the tradeoff was worth accepting.</p><p>Newer models have the judgement to make that call themselves, so the rule stopped paying for itself.</p><p>What replaced it is a principle rather than a prohibition.</p><p>Write code that reads like the code around it, matching its comment density, its naming, its idiom.</p><p>The rule gives a fixed answer that is wrong for some prompts.</p><p>The principle gives Claude a way to find the right answer by reading the repo.</p><p>So it adapts to a codebase the rule-writer never saw.</p><p>Apply that to every absolute you have written.</p><p>&quot;Always X&quot; becomes &quot;X is usually right here because of this reason.&quot;</p><p>&quot;Never Y&quot; becomes &quot;prefer Z, Y is a known gotcha in this repo.&quot;</p><p>Keep as hard rules only what Claude genuinely cannot infer.</p><p>Destructive operations, security boundaries, compliance, and the gotchas that are invisible from the code itself.</p><p>That is the shape every line should take.</p><p>Not what to output.</p><p>What to look at.</p><hr><h2 id="a-tree-not-a-scroll" tabindex="-1">A tree, not a scroll <a class="header-anchor" href="#a-tree-not-a-scroll" aria-label="Permalink to &quot;A tree, not a scroll&quot;">​</a></h2><p>The myth that inflates every CLAUDE.md is the belief that it must hold every practice you might ever need.</p><p>Because otherwise Claude will not find it.</p><p>That was once close to true. It is not now.</p><p>Anthropic ran this on themselves.</p><p>Their system prompt carried detailed code review and verification instructions.</p><p>Unnecessary for most requests, crucial for a few.</p><p>Rather than pay for it every time, they moved verification and code review into skills Claude calls selectively.</p><p>The information did not get worse.</p><p>It stopped being mandatory reading.</p><p>The mechanics are worth knowing precisely, because they tell you what each layer actually costs.</p><p>Skill descriptions load at startup, one line each, so Claude knows what it can invoke. The full body loads only on use.</p><p>Rules in .claude/rules/ with a paths pattern load automatically when Claude reads a matching file, and cost nothing until then.</p><p>A skill marked disable-model-invocation stays completely out of context, not even its description, until you invoke it by name.</p><p>That is the right setting for anything with side effects. Committing, deploying, sending messages.</p><p>For the project CLAUDE.md, Anthropic&#39;s own guidance is a hard number.</p><p>Keep it under 200 lines, and move reference content into skills or path-scoped rules.</p><p>What earns its place:</p><ul><li>A one-line statement of what the repo is for.</li><li>The unwritten conventions nobody wrote down but everybody follows.</li><li>The thing that looks like a bug and is not.</li><li>The decision Claude would otherwise violate reasonably, like all shared types living in one monolithic file.</li><li>Pointers to the deeper guides, not the guides themselves.</li></ul><p>What does not earn its place is anything Claude can learn by listing your directories.</p><p>Your framework, your test runner, your folder layout, your language version.</p><p>Claude reads the file system.</p><p>Describing the repo is the single fastest way to a thousand-line CLAUDE.md that tells Claude nothing it did not already know.</p><p>[圖 3]</p><p>One mechanic almost nobody knows, which should change how you write skills.</p><p>After a session compacts, invoked skill bodies are re-injected.</p><p>But capped at 5,000 tokens per skill and 25,000 tokens total, with the oldest dropped first.</p><p>Truncation keeps the start of the file.</p><p>So put your most important instructions near the top of every SKILL.md, and split long skills into branch files.</p><p>A skill that buries its critical rule on line 400 will silently lose it in any long session.</p><hr><h2 id="defer-the-tools-too" tabindex="-1">Defer the tools too <a class="header-anchor" href="#defer-the-tools-too" aria-label="Permalink to &quot;Defer the tools too&quot;">​</a></h2><p>Progressive disclosure is not only for documents.</p><p>By default Claude Code loads MCP tool names only, around 120 tokens.</p><p>The full schemas stay deferred, and Claude fetches specific ones on demand through tool search when a task needs them.</p><p>The consequence is a real change in what you can build.</p><p>Tool descriptions are context, and a large toolset used to mean a permanently crowded window.</p><p>Which is why teams pruned useful servers just to stay lean.</p><p>Deferred loading breaks that tradeoff.</p><p>Connect many more tools without any of them taxing a request that does not need them.</p><p>There is a research finding behind why this works so well.</p><p>Too many tools with overlapping descriptions actively confuses model selection, the confusion mode from earlier.</p><p>Applying retrieval to tool descriptions rather than dumping them all in has been shown to improve tool selection accuracy roughly threefold.</p><p>Deferring is not just cheaper.</p><p>It picks better.</p><hr><h2 id="send-the-reading-somewhere-else" tabindex="-1">Send the reading somewhere else <a class="header-anchor" href="#send-the-reading-somewhere-else" aria-label="Permalink to &quot;Send the reading somewhere else&quot;">​</a></h2><p>Everything above is the context you author.</p><p>The harder half is the flood that arrives while Claude works. File reads, tool output, conversation.</p><p>File reads dominate.</p><p>A single source file runs 1,000 to 2,500 tokens.</p><p>A research task that touches a dozen files will quietly eat a third of your window before Claude writes a line.</p><p>Delegate that reading instead.</p><p>A subagent gets its own separate context window.</p><p>Its own shorter system prompt, its own copy of CLAUDE.md, the same MCP servers and skills, but none of your conversation history.</p><p>It reads as many files as it needs over there.</p><p>In Anthropic&#39;s worked example the subagent consumed 6,100 tokens of file reads and returned a 420-token summary.</p><p>That ratio is the entire point.</p><p>You paid 420 tokens for work that would have cost you 6,100.</p><p>The instruction is as simple as saying so.</p><p>Use a subagent to research this, then fix it.</p><p>Isolation has a real cost, and it is worth stating honestly.</p><p>Anthropic has reported multi-agent setups using up to fifteen times more tokens than chat, because every subagent reloads its own core.</p><p>You are trading total tokens for a clean main window.</p><p>Usually the right trade, and always a deliberate one.</p><hr><h2 id="compress-on-purpose-not-on-panic" tabindex="-1">Compress on purpose, not on panic <a class="header-anchor" href="#compress-on-purpose-not-on-panic" aria-label="Permalink to &quot;Compress on purpose, not on panic&quot;">​</a></h2><p>Long sessions fill up.</p><p>Claude Code handles it automatically.</p><p>Compaction runs in two stages, clearing older tool outputs first and summarizing the conversation if that is not enough.</p><p>So a full window never ends your session.</p><p>But automatic compaction guesses at what matters.</p><p>You can do better by compressing deliberately, before the automatic pass fires.</p><p>Two commands, two different jobs.</p><p>/compact takes an instruction, so &quot;compact, focus on the auth bug fix&quot; keeps what you chose.</p><p>/clear wipes history entirely, and it is badly underused.</p><p>If the next task does not meaningfully depend on the last twenty messages, old conversation is pure noise crowding out files you are about to need.</p><p>Now the part that catches people.</p><p>Not everything survives compaction equally.</p><p>Project-root CLAUDE.md and auto memory are re-injected from disk.</p><p>But rules with paths frontmatter and nested CLAUDE.md files live in message history.</p><p>They get summarized away and do not return until Claude reads a matching file again.</p><p>If a rule genuinely must persist, drop the paths scoping or move it to the project root.</p><hr><h2 id="six-context-jobs-to-run-this-week" tabindex="-1">Six context jobs to run this week <a class="header-anchor" href="#six-context-jobs-to-run-this-week" aria-label="Permalink to &quot;Six context jobs to run this week&quot;">​</a></h2><p>Open your window and read it.</p><p>Run /context at session start, then again after an hour of work. Watch memory files and free space.</p><p>If memory files are heavy, you just diagnosed an overweight CLAUDE.md in one command.</p><p>Get the cut list generated for you.</p><p>Run /doctor and Claude reads your skills and CLAUDE.md and flags overconstraining absolutes, cross-file contradictions, and split candidates.</p><p>Hunt contradictions across files.</p><p>Have Claude read CLAUDE.md and every skill together and list pairs of instructions that cannot both be followed.</p><p>Those are the lines quietly taxing every request you make.</p><p>Split the trunk into a tree.</p><p>Anything longer than a few lines becomes a skill or a path-scoped rule with a pointer left behind. Target: under 200 lines.</p><p>Delegate the reading.</p><p>Any research task touching more than a few files goes to a subagent. Check /context before and after. The flat line sells it.</p><p>Move state onto the filesystem.</p><p>Have Claude keep a plan file it rewrites as it works.</p><p>It survives compaction because it lives on disk, and long tasks stop losing the thread halfway through.</p><hr><h2 id="if-the-model-is-the-cpu-the-context-window-is-the-ram" tabindex="-1">If the model is the CPU, the context window is the RAM. <a class="header-anchor" href="#if-the-model-is-the-cpu-the-context-window-is-the-ram" aria-label="Permalink to &quot;If the model is the CPU, the context window is the RAM.&quot;">​</a></h2><p>Every line you add is a line that loads on every request, forever.</p><p>Context is not free storage.</p><p>It is a standing cost.</p><p>The architects went the other direction.</p><p>They measured before they touched anything.</p><p>They cut four fifths and lost nothing.</p><p>They swapped prohibitions for principles, scrolls for trees, eager tools for searched ones.</p><p>And sent the heavy reading somewhere else entirely.</p><p>Most people will keep appending to a window they have never opened.</p><p>Follow me and subscribe to my Telegram channel: <a href="https://t.me/+75nMf005jRpjMDU1" target="_blank" rel="noreferrer">https://t.me/+75nMf005jRpjMDU1</a></p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Context engineering 的核心是「刪除優先、測量其次」——CLAUDE.md 常駐內容視為有罪推定，用規則換判斷、用樹狀結構取代單一長捲軸、把讀檔委派給 subagent，並掌握「哪些內容在 compact 後會消失」的具體機制。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>四種失敗模式</strong>（Drew Breunig 分類）：Poisoning（幻覺污染下游推理）、Distraction（context 過大壓過模型自身知識）、Confusion（無關內容誤導選擇）、Clash（context 內部矛盾）——前三種是自然發生的，<strong>Clash 是自己寫進去的</strong>，且是最隱蔽昂貴的一種（每次請求都要先消化矛盾，輸出仍看起來正常）</li><li><strong>刪除優先於測量</strong>：Anthropic 為 Claude 5 世代砍除系統提示詞 80% 以上，coding eval 零損失；方法論：建最小 eval harness（10 個 prompt + rubric）→ 整塊刪除（不要一次刪一行）→ 跑 harness → 只還原真的壞掉的部分</li><li><strong>規則換判斷</strong>：舊模型需要「絕對禁止 X」的硬規則，新模型有能力自行判斷；&quot;Always X&quot; 改寫為「X 通常是對的，因為 Y」，&quot;Never Y&quot; 改寫為「優先用 Z，Y 是本 repo 已知的坑」；只把「模型真的無法從程式碼推斷出來」的東西（破壞性操作、安全邊界、合規、隱性 gotcha）留為硬規則</li><li><strong>樹狀結構取代單一捲軸</strong>：CLAUDE.md 官方建議上限 200 行；skill 描述在啟動時只載入一行，完整內文按需載入；rules 帶 <code>paths</code> frontmatter 只在讀到匹配檔案時才載入；標記 <code>disable-model-invocation</code> 的 skill 完全不進 context 直到被明確呼叫（適用於有副作用的操作，如 commit/deploy/發訊息）</li><li><strong>讀檔委派給 subagent</strong>：subagent 有獨立 context window，官方案例中 subagent 消耗 6,100 tokens 讀檔換回 420 tokens 摘要；但多 agent 設定總 token 消耗可達單一對話的 15 倍，是刻意的 trade-off 而非免費午餐</li><li><strong>compact 機制細節</strong>：<code>/compact</code> 帶指令保留指定重點，<code>/clear</code> 完全清空歷史；<strong>關鍵機制</strong>：project-root CLAUDE.md 與 auto memory 會從磁碟重新注入，但帶 <code>paths</code> frontmatter 的 rules 與巢狀 CLAUDE.md 活在訊息歷史中，會被摘要掉，直到再次讀到匹配檔案才恢復——若規則必須存活，需拿掉 paths scoping 或移到 project root</li><li><strong>skill 在 compact 後的截斷機制</strong>：已呼叫的 skill body 會在 compact 後重新注入，但<strong>單一 skill 上限 5,000 tokens、總計上限 25,000 tokens，最舊的先被丟棄，且截斷保留檔案開頭</strong>——關鍵指令應放在 SKILL.md 最前面，長 skill 應拆成分支檔案</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>官方 session 模擬：約 7,850 tokens 在使用者輸入任何內容前就已載入（vs 使用者輸入平均 45 tokens）</li><li>Auto memory 上限：前 200 行或 25KB（取先達到者）</li><li>Claude 5 世代系統提示詞刪減 &gt; 80%，coding eval 零損失</li><li>Subagent 委派讀檔案例：6,100 tokens 讀檔 → 420 tokens 摘要回傳</li><li>多 agent 設定總 token 消耗可達單一對話 15 倍</li><li>Tool description 用 retrieval（deferred loading）取代全量載入，tool selection 準確率提升約 3 倍</li><li>相關指令：<code>/context</code>、<code>/memory</code>、<code>/usage</code>、<code>/compact &lt;指令&gt;</code>、<code>/clear</code>、<code>/doctor</code></li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>「rules 帶 <code>paths</code> frontmatter 與巢狀 CLAUDE.md 不會在 compact 後從磁碟重新注入，只有 project-root CLAUDE.md 與 auto memory 會」——這是本 workspace <code>context-management.md</code> 目前<strong>未明確記載</strong>的具體機制細節，若屬實對 auto-load 規則設計（<code>.claude/rules/*.md</code> 均為 project-root 常駐，不受此影響；但 path-scoped 規則如 <code>security-hygiene.md</code>/<code>prompt-lifecycle.md</code> 可能受影響）有直接參考價值，建議後續查證官方文件後評估補充</li><li>「skill body compact 後重新注入上限 5,000/25,000 tokens、截斷保留開頭」若屬實，直接影響本 workspace 所有長 SKILL.md 的撰寫慣例（關鍵指令應置頂），與現有 skill 撰寫慣例（多數已有摘要在前）部分吻合但未見明文記載此機制</li><li>全文數字多引用 Anthropic 官方 session 模擬與案例，但未附原始連結，屬轉述整理而非可獨立查核的一手數據，社群推文性質下證據品質上限 6</li><li>內容與本 workspace <code>context-management.md</code>（Progressive Disclosure、Static-first 快取五禁令、Compact 紀律）三個段落幾乎逐項對應，可視為對現有規則設計方向的外部驗證，同時補充了兩個目前規則未載明的具體機制（compact 存活範圍、skill 截斷上限）</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>提出 workspace 現有 <code>context-management.md</code> 未載明的兩個具體機制（compact 存活範圍、skill 截斷上限），可直接查證後補充</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>整合 Drew Breunig 四失效模式分類法 + Anthropic 官方機制細節，Clash 模式的「自己寫的隱性稅」框架有新意</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>引用具體數字與官方案例，但未附原始連結可查核，社群推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>具體指令（/context /doctor /compact /clear）+ 精確機制數字（5000/25000 tokens、200行上限）</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用任何使用 Claude Code + CLAUDE.md/skills/rules 架構的專案</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.85/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：與本 workspace <code>context-management.md</code> 高度重疊且補充兩個未載明的具體機制（compact 存活範圍、skill 截斷上限），建議查證官方文件後評估納入該規則檔，本次先歸檔待後續整合。</p>',227)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
